KEYS += ["Show original", "Show translation"]
TRANSLATION_LABELS = {'es': 'Ver original|Ver traducción', 'ru': 'Показать оригинал|Показать перевод', 'pl': 'Pokaż oryginał|Pokaż tłumaczenie', 'ca': 'Mostra l’original|Mostra la traducció', 'ca-valencia': 'Mostra l’original|Mostra la traducció', 'uk': 'Показати оригінал|Показати переклад', 'zh-Hans': '显示原文|显示译文', 'ko': '원문 보기|번역 보기', 'ja': '原文を表示|翻訳を表示', 'it': 'Mostra originale|Mostra traduzione', 'pt': 'Mostrar original|Mostrar tradução', 'el': 'Εμφάνιση πρωτοτύπου|Εμφάνιση μετάφρασης', 'eu': 'Erakutsi jatorrizkoa|Erakutsi itzulpena', 'gl': 'Ver orixinal|Ver tradución', 'oc-aran': 'Veir er originau|Veir era traduccion', 'an': 'Veyer l’orichinal|Veyer a traducción'}
for language, labels in TRANSLATION_LABELS.items():
    ROWS[language] += "|" + labels

def extend(catalogues):
    for language,row in ROWS.items():
        values=row.split('|')
        if len(values)!=len(KEYS):raise ValueError(language)
        catalogues.setdefault(language,{}).update(zip(KEYS,values))
